import React from 'react';
// Inline SVG (via SVGR) so diagrams use page fonts, stay sharp and keep selectable text.
// Sources are generated by tools/render_overview.py.
import Link from '@docusaurus/Link';
import Overview from '@site/media/overview.svg';
import OverviewHome from '@site/media/overview-home.svg';
import Architecture from '@site/media/architecture.svg';

function Figure({children, label}: {children: React.ReactNode; label: string}) {
  return (
    <figure className="bolt-diagram" role="img" aria-label={label}>
      {children}
    </figure>
  );
}

export function OverviewFigure() {
  return (
    <Figure label="Modular observations, seamless sim-to-real and policy-step latency">
      <Overview />
    </Figure>
  );
}

export function ArchitectureFigure() {
  return (
    <Figure label="PolicyLoop over the RobotBackend interface with MuJoCo, G1, RP1 and custom robot backends">
      <Architecture />
    </Figure>
  );
}

// Homepage variant: each card of the figure links to its docs page.
// Geometry matches tools/render_overview.py (W=1200, H=440+40, PAD=GAP=24).
const HOME = {w: 1200, h: 480, pad: 24, gap: 24};
const cardWidth = (HOME.w - 2 * HOME.pad - 2 * HOME.gap) / 3;
const homeLinks = [
  {to: '/core/observations', label: 'Modular observations'},
  {to: '/core/backends', label: 'Seamless sim-to-real'},
  {to: '/reference/performance', label: 'Fast native C++'},
];

export function OverviewHomeFigure() {
  const pct = (v: number, total: number) => `${(100 * v) / total}%`;
  return (
    <figure className="bolt-diagram bolt-diagram--linked">
      <OverviewHome role="img" aria-label="Modular observations, seamless sim-to-real and policy-step latency" />
      {homeLinks.map((link, i) => (
        <Link
          key={link.to}
          to={link.to}
          className="bolt-diagram__card"
          aria-label={`Learn more: ${link.label}`}
          style={{
            left: pct(HOME.pad + i * (cardWidth + HOME.gap), HOME.w),
            top: pct(HOME.pad, HOME.h),
            width: pct(cardWidth, HOME.w),
            height: pct(HOME.h - 2 * HOME.pad, HOME.h),
          }}
        />
      ))}
    </figure>
  );
}
